export const wranglerConfig = `# wrangler.toml - Cloudflare Workers & D1 Configuration
# Generated by AI Studio Construction Accounting Suite

name = "construction-accounting"
main = "worker.js"
compatibility_date = "2024-03-01"

[vars]
BACKUP_SECRET_TOKEN = "your_secure_random_token_here" # Token used for automatic Windows backups

[assets]
directory = "./dist"

[[d1_databases]]
binding = "DB"
database_name = "construction-accounting-db"
database_id = "your-cloudflare-d1-database-uuid-here"
`;

export const d1SchemaSql = `-- D1 SQL Schema Initialization for Construction Contracting Accounting
-- Execute this via: wrangler d1 execute construction-accounting-db --remote --file=schema.sql

CREATE TABLE IF NOT EXISTS companies (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  code TEXT
);

CREATE TABLE IF NOT EXISTS projects (
  id TEXT PRIMARY KEY,
  company_id TEXT,
  name TEXT NOT NULL,
  address TEXT,
  total_area REAL,
  budget REAL,
  stages TEXT, -- Store JSON string of stages
  current_stage TEXT,
  status TEXT
);

CREATE TABLE IF NOT EXISTS accounts (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  type TEXT,
  type_name TEXT,
  account_number TEXT,
  bank_name TEXT,
  balance REAL
);

CREATE TABLE IF NOT EXISTS materials (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  category TEXT,
  unit TEXT,
  stock REAL,
  average_price REAL
);

CREATE TABLE IF NOT EXISTS material_transactions (
  id TEXT PRIMARY KEY,
  project_id TEXT,
  material_id TEXT,
  type TEXT,
  quantity REAL,
  unit_price REAL,
  date TEXT,
  person_name TEXT,
  description TEXT
);

CREATE TABLE IF NOT EXISTS transactions (
  id TEXT PRIMARY KEY,
  company_id TEXT,
  project_id TEXT,
  type TEXT,
  category TEXT,
  sub_category TEXT,
  amount REAL,
  account_id TEXT,
  person_name TEXT,
  date TEXT,
  description TEXT,
  is_non_cash INTEGER DEFAULT 0,
  barter_property_type TEXT,
  barter_description TEXT,
  barter_agreed_value REAL,
  attachment_name TEXT,
  attachment_data TEXT -- Store base64 data for electronic archiving
);

CREATE TABLE IF NOT EXISTS checks (
  id TEXT PRIMARY KEY,
  company_id TEXT,
  project_id TEXT,
  check_number TEXT,
  bank_name TEXT,
  due_date TEXT,
  amount REAL,
  type TEXT,
  status TEXT,
  person_name TEXT,
  description TEXT
);

CREATE TABLE IF NOT EXISTS units (
  id TEXT PRIMARY KEY,
  project_id TEXT,
  unit_number TEXT,
  floor TEXT,
  area REAL,
  price_per_meter REAL,
  total_price REAL,
  status TEXT,
  buyer_name TEXT,
  down_payment REAL,
  barter_property TEXT
);
`;

export const workerJs = `// Cloudflare Worker Script (worker.js)
// Complete Serverless REST API for Farsi Construction Accounting Suite, integrated with Cloudflare D1.

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    const path = url.pathname;
    const method = request.method;

    // CORS Headers
    const corsHeaders = {
      "Access-Control-Allow-Origin": "*",
      "Access-Control-Allow-Methods": "GET, POST, PUT, DELETE, OPTIONS",
      "Access-Control-Allow-Headers": "Content-Type, Authorization, X-Backup-Token",
      "Content-Type": "application/json"
    };

    if (method === "OPTIONS") {
      return new Response(null, { headers: corsHeaders });
    }

    // Serve static assets from Wrangler directory using the ASSETS binding
    // Any requests that do not match '/api/' are treated as static assets or fallback to index.html
    if (!path.startsWith("/api/")) {
      if (env.ASSETS) {
        try {
          const hasExtension = path.includes(".");
          const assetRequest = hasExtension 
            ? request 
            : new Request(url.origin + "/index.html", request);
          
          const assetResponse = await env.ASSETS.fetch(assetRequest);
          if (assetResponse.status < 400) {
            return assetResponse;
          }
        } catch (err) {
          // Fall through
        }
      }
    }

    try {
      // 1. Database SQL Export Endpoint (Secure Windows Backup Service)
      if (path === "/api/backup" && method === "GET") {
        const token = url.searchParams.get("token") || request.headers.get("X-Backup-Token");
        if (!token || token !== env.BACKUP_SECRET_TOKEN) {
          return new Response(JSON.stringify({ error: "Access Denied: Invalid backup token" }), {
            status: 401,
            headers: corsHeaders
          });
        }

        // Export all tables contents
        const tables = ["companies", "projects", "accounts", "materials", "transactions", "checks", "units"];
        let exportDump = \`-- Cloudflare D1 Construction Accounting SQL Backup\\n-- Date: \${new Date().toISOString()}\\n\\n\`;

        for (const table of tables) {
          const { results } = await env.DB.prepare(\`SELECT * FROM \${table}\`).all();
          exportDump += \`-- Dump of table \${table}\\n\`;
          for (const row of results) {
            const keys = Object.keys(row);
            const vals = keys.map(k => {
              const val = row[k];
              if (val === null) return "NULL";
              if (typeof val === "string") return "'" + val.replace(/'/g, "''") + "'";
              return val;
            });
            exportDump += \`INSERT OR REPLACE INTO \${table} (\${keys.join(", ")}) VALUES (\${vals.join(", ")});\\n\`;
          }
          exportDump += "\\n";
        }

        return new Response(exportDump, {
          headers: {
            ...corsHeaders,
            "Content-Type": "application/sql",
            "Content-Disposition": "attachment; filename=d1_construction_backup.sql"
          }
        });
      }

      // 2. Query Project List
      if (path === "/api/projects" && method === "GET") {
        const { results } = await env.DB.prepare("SELECT * FROM projects").all();
        return new Response(JSON.stringify(results), { headers: corsHeaders });
      }

      // 3. Register a New Transaction
      if (path === "/api/transactions" && method === "POST") {
        const tx = await request.json();
        const txId = tx.id || "t_" + Date.now();
        
        await env.DB.prepare(\`
          INSERT INTO transactions (id, company_id, project_id, type, category, sub_category, amount, account_id, person_name, date, description, is_non_cash, attachment_name)
          VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        \`).bind(
          txId,
          tx.companyId || "c1",
          tx.projectId,
          tx.type,
          tx.category,
          tx.subCategory || null,
          tx.amount,
          tx.accountId,
          tx.personName,
          tx.date,
          tx.description,
          tx.isNonCash ? 1 : 0,
          tx.attachmentName || null
        ).run();

        // Adjust local account balances in D1
        if (!tx.isNonCash && tx.accountId) {
          const diff = tx.type === "expense" ? -tx.amount : tx.amount;
          await env.DB.prepare("UPDATE accounts SET balance = balance + ? WHERE id = ?").bind(diff, tx.accountId).run();
        }

        return new Response(JSON.stringify({ success: true, id: txId }), { headers: corsHeaders });
      }

      // Fallback response for other endpoints
      return new Response(JSON.stringify({ 
        message: "Welcome to Cloudflare Workers D1 Construction Accounting API",
        available_endpoints: [
          "GET /api/projects",
          "POST /api/transactions",
          "GET /api/backup?token=YOUR_SECRET"
        ]
      }), { headers: corsHeaders });

    } catch (err) {
      return new Response(JSON.stringify({ error: err.message }), {
        status: 500,
        headers: corsHeaders
      });
    }
  }
};
`;
